<style>
body{margin:0;background:{{ $colors['background'] }};color:{{ $colors['text_color'] }};font-family:{{ $font }}}.catalog{max-width:1120px;margin:auto;padding:30px 22px 90px}.catalog h1{font-size:clamp(32px,6vw,58px);line-height:1.05;letter-spacing:-.035em;font-weight:750;margin:15px 0 22px}.catalog h2{font-size:25px;font-weight:700;margin:0 0 18px}.catalog h3{font-size:23px;line-height:1.2;font-weight:700;margin:16px 0 10px}.catalog h4{font-size:16px;font-weight:700;margin:18px 0 8px}.catalog p{line-height:1.6}.catalog a{color:inherit}.catalog-hero{display:flex;align-items:center;gap:35px;margin:8px 0 30px;padding:36px;border-radius:24px;background:{{ $colors['surface'] }};border:1px solid color-mix(in srgb,currentColor 12%,transparent)}.hero-copy{flex:1}.eyebrow{font-size:11px;letter-spacing:.16em;font-weight:700}.hero-image{width:42%;aspect-ratio:4/3;object-fit:cover;border-radius:14px}.courses .catalog-hero{border-top:5px solid {{ $colors['accent'] }};border-radius:8px 8px 24px 24px}.properties .catalog-hero{border-left:5px solid {{ $colors['accent'] }}}.contact-links{display:flex;gap:16px;font-size:14px;margin-top:20px}.catalog-filters{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:12px;padding:20px 0;border-top:1px solid color-mix(in srgb,currentColor 18%,transparent);border-bottom:1px solid color-mix(in srgb,currentColor 18%,transparent)}.catalog label{font-size:12px;display:block;font-weight:600}.catalog input,.catalog select,.catalog textarea{font:inherit;display:block;width:100%;box-sizing:border-box;border:1px solid color-mix(in srgb,currentColor 30%,transparent);background:{{ $colors['surface'] }};color:inherit;border-radius:8px;padding:11px;margin-top:6px}.catalog-section{margin:32px 0}.listing-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;align-items:start}.listing{border:1px solid color-mix(in srgb,currentColor 15%,transparent);background:{{ $colors['surface'] }};border-radius:16px;overflow:hidden;scroll-margin-top:20px}.listing-photo{width:100%;aspect-ratio:16/10;object-fit:cover}.listing-placeholder{aspect-ratio:16/8;background:color-mix(in srgb,{{ $colors['accent'] }} 12%,{{ $colors['surface'] }});display:grid;place-items:center;font-size:40px;color:inherit}.listing-content{padding:24px}.listing-tags{display:flex;gap:8px;flex-wrap:wrap;font-size:11px;font-weight:650}.listing-tags span{padding:5px 10px;border:1px solid color-mix(in srgb,currentColor 22%,transparent);border-radius:50px}.listing-price{font-size:22px;font-weight:700;margin:12px 0}.listing-price small{font-size:12px;font-weight:400;display:block}.listing-meta{font-size:13px}.property-facts,.course-facts{display:flex;gap:14px;flex-wrap:wrap;padding:12px 0;font-size:13px;border-block:1px solid color-mix(in srgb,currentColor 15%,transparent)}.course-facts span{padding:5px 9px;background:color-mix(in srgb,{{ $colors['accent'] }} 9%,{{ $colors['surface'] }});border-radius:5px}.courses .listing-photo,.courses .listing-placeholder{aspect-ratio:2/1}.instructor,.listing-location{font-size:13px}.listing-details{margin:18px 0}.catalog summary{cursor:pointer;font-size:14px;font-weight:650;line-height:1.5}.preserve-lines{white-space:pre-wrap;font-size:14px}.photo-gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:15px 0}.photo-gallery img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:7px}.amenities{display:flex;flex-wrap:wrap;gap:8px;list-style:none;padding:0;font-size:12px}.amenities li{padding:6px 10px;border:1px solid currentColor;border-radius:5px}.syllabus{padding-left:22px;font-size:14px;line-height:1.8;list-style:decimal}.batch-info{border-left:3px solid {{ $colors['accent'] }};padding:2px 15px;margin:15px 0}.batch-info p{font-size:13px;margin:6px 0}.batch-info small{font-size:12px}.listing-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:18px}.catalog button,.external-action{font:inherit;font-size:13px;font-weight:650;background:{{ $colors['accent'] }};color:{{ $accentInk }}!important;border:0;border-radius:8px;padding:11px 15px;cursor:pointer;text-decoration:none}.permalink{font-size:12px;text-decoration:underline}.inquiry-form{border-top:1px solid color-mix(in srgb,currentColor 20%,transparent);padding-top:16px;margin-top:20px}.inquiry-form label{margin:12px 0}.inquiry-form .consent{display:flex;align-items:flex-start;gap:8px;font-weight:400;line-height:1.5}.consent input{width:auto;flex-shrink:0}.request-note{font-size:12px}.notice{padding:18px;border-left:4px solid {{ $colors['accent'] }};background:{{ $colors['surface'] }};margin:18px 0}.catalog-empty{text-align:center;padding:55px 20px}.honeypot{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}.catalog.list .listing-grid{grid-template-columns:1fr}.catalog.list .listing{display:grid;grid-template-columns:minmax(200px,35%) 1fr}.catalog.list .listing-photo,.catalog.list .listing-placeholder{height:100%;aspect-ratio:auto;min-height:230px}.catalog button:hover,.external-action:hover{filter:brightness(.95)}.catalog :focus-visible{outline:3px solid currentColor;outline-offset:3px}[hidden]{display:none!important}
@media(max-width:800px){.catalog-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-filters label:first-child{grid-column:1/-1}.catalog-hero{padding:24px;gap:20px}.hero-image{width:35%}}
@media(max-width:600px){.catalog{padding:20px 16px 80px}.catalog-hero{display:block}.hero-image{width:100%;margin-top:22px;aspect-ratio:16/9}.listing-grid{grid-template-columns:1fr}.catalog.list .listing{display:block}.catalog.list .listing-photo,.catalog.list .listing-placeholder{height:auto;aspect-ratio:16/9;min-height:0}.listing-content{padding:20px}}
</style>
